package adaptivelearning.module.contentgen.entity;
import adaptivelearning.config.app.BaseEntity; import adaptivelearning.shared.enums.GenerationStatus; import jakarta.persistence.*; import java.time.LocalDateTime; import lombok.Getter; import lombok.Setter;
@Entity @Table(name="content_generations") @Getter @Setter
public class ContentGeneration extends BaseEntity { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long generationId; private Long requestedBy; private Long certificateId; private Long topicId; @Column(length=50) private String generationType; @Column(columnDefinition="TEXT") private String prompt; @Column(columnDefinition="TEXT") private String parametersJson; @Column(columnDefinition="TEXT") private String resultJson; @Enumerated(EnumType.STRING) @Column(nullable=false) private GenerationStatus status; private String model; private int itemCount; @Column(columnDefinition="TEXT") private String errorMessage; private LocalDateTime startedAt; private LocalDateTime completedAt; }
